var go=UnityEngine.GameObject.Find("CM_EntranceBay01_PaintedReview_v01");
if(go==null)throw new System.Exception("Entrance review not active");
var meshes=go.GetComponentsInChildren<UnityEngine.MeshFilter>();int tris=0,verts=0,issues=0;var bounds=new UnityEngine.Bounds();bool first=true;
foreach(var mf in meshes){var m=mf.sharedMesh;tris+=m.triangles.Length/3;verts+=m.vertexCount;if(m.uv.Length!=m.vertexCount||m.normals.Length!=m.vertexCount)issues++;foreach(var uv in m.uv)if(uv.x<-.00001f||uv.x>1.00001f||uv.y<-.00001f||uv.y>1.00001f)issues++;foreach(var n in m.normals)if(float.IsNaN(n.x)||n.sqrMagnitude<.9f||n.sqrMagnitude>1.1f)issues++;foreach(var v in m.vertices){var p=mf.transform.TransformPoint(v);if(first){bounds=new UnityEngine.Bounds(p,UnityEngine.Vector3.zero);first=false;}else bounds.Encapsulate(p);}var r=mf.GetComponent<UnityEngine.Renderer>();if(r.sharedMaterials.Length!=m.subMeshCount)issues++;foreach(var mat in r.sharedMaterials)if(mat==null||mat.shader.name!="Universal Render Pipeline/Lit"||mat.GetTexture("_BaseMap")==null)issues++;}
if(tris!=20040||meshes.Length!=95||issues!=0)throw new System.Exception("Imported geometry/material validation failed: "+issues);
if(UnityEngine.Vector3.Distance(bounds.min,new UnityEngine.Vector3(-1.859728f,0,-.32f))>.001f||UnityEngine.Vector3.Distance(bounds.max,new UnityEngine.Vector3(1.859829f,3.757379f,1.074909f))>.001f)throw new System.Exception("Axis/bounds mismatch");
if(go.transform.localScale!=UnityEngine.Vector3.one||go.transform.rotation!=UnityEngine.Quaternion.identity)throw new System.Exception("Root transform mismatch");
var d=meshes.First(m=>m.name=="03_Door_Leaf_Hinged");if(UnityEngine.Vector3.Distance(d.transform.localPosition,new UnityEngine.Vector3(-.89f,.2f,-.03f))>.001f)throw new System.Exception("Hinge pivot mismatch");
var report="PASS: meshes="+meshes.Length+" triangles="+tris+" imported vertices="+verts+" UV/normal/material issues="+issues+" min="+bounds.min.ToString("F5")+" max="+bounds.max.ToString("F5")+" rootScale="+go.transform.localScale+" rootRotation="+go.transform.eulerAngles+" hingePivot="+d.transform.localPosition+" colliders="+go.GetComponentsInChildren<UnityEngine.Collider>().Length+" compilationFailed="+UnityEditor.EditorUtility.scriptCompilationFailed;
System.IO.File.WriteAllText("ArtSource/Blender/Architecture/CrookedMortar/EntranceBay01/unity_validation.txt",report);return report;
